python
def stampGatesThresholdFile(readings, k):
    a=readings
    out=[]
    for x in a: out.append(max(0,x))
    return sum(x>=k for x in out)


java
class Solution {
  public int stampGatesThresholdFile(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a)out.add(Math.max(0,x));}
    int answer=0;for(int x:out)if(x>=k)answer++;return answer;
  }
}
